/* The home story reuses the approved photographic assets and existing routes. */
(() => {
 const portrait=()=>'<div class="hiw-avatars"><i>AL</i><i>BE</i><i>GI</i><i>FE</i><i>DA</i></div>';
 const ribbon='<svg class="hiw-ribbon" viewBox="0 0 800 430" preserveAspectRatio="none" aria-hidden="true"><path d="M-60 320C90 435 112 65 268 110S245 362 434 319 488 36 658 98 745 279 866 160"/></svg>';
 const photo=(name,cls='')=>`<img class="${cls}" src="assets/${name}-scene.png" alt="" loading="lazy" width="420" height="420">`;
 const scenes=[
  `<div class="hiw-branches"><div class="hiw-branch hiw-branch-gift">${photo('speaker')}<strong>Scelgo il regalo prima</strong></div><span class="hiw-branch-or">o</span><div class="hiw-branch hiw-branch-people">${portrait()}<strong>Raccolgo adesioni prima</strong></div></div>`,
  `<div class="hiw-invitation-scene"><div class="hiw-invitation-paper"><img class="hiw-paper-mark" src="assets/gifty-ribbon.svg" alt=""><strong>Il regalo per Mauro</strong>${portrait()}<div class="hiw-link-drawing"><span></span><span></span><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="8" y="8" width="12" height="12" rx="2"/><path d="M16 5V3H3v13h2"/></svg></div></div><div class="hiw-invitation-option hiw-option-one">${photo('lamp')}</div><div class="hiw-invitation-option hiw-option-two">${photo('bag')}</div><div class="hiw-share-orbit"><svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="23" cy="6" r="4"/><circle cx="7" cy="16" r="4"/><circle cx="23" cy="26" r="4"/><path d="m10.5 14 9-6m-9 10 9 6"/></svg></div></div>`,
  `<div class="hiw-card-scene"><div class="hiw-envelope"></div><div class="hiw-signed-card"><img src="assets/gifty-ribbon.svg" alt=""><span class="hiw-handwritten">Per te,<br>da tutti noi</span>${portrait()}<svg class="hiw-drawn-heart" viewBox="0 0 54 50" fill="none" stroke="currentColor" stroke-width="3"><path d="M27 43C6 29-2 11 10 6c9-5 15 5 17 10C32 1 45 1 48 11c4 10-5 22-21 32Z"/></svg></div></div>`,
  `<div class="hiw-delivery-scene"><div class="hiw-delivery-product">${photo('speaker')}</div><div class="hiw-delivery-note"><img src="assets/gifty-ribbon.svg" alt=""><span class="hiw-handwritten">Per te,<br>da tutti noi</span>${portrait()}</div></div>`,
  `<div class="hiw-ledger-scene"><div class="hiw-ledger-paper"><div class="hiw-ledger-top"><img src="assets/gifty-ribbon.svg" alt=""><strong>Il regalo per Mauro</strong></div><div class="hiw-ledger-row"><i>AL</i><span>Ricevuto</span><b class="hiw-check">✓</b></div><div class="hiw-ledger-row"><i>BE</i><span>Da verificare</span><b>···</b></div><div class="hiw-ledger-row"><i>GI</i><span>Da ricevere</span><b>—</b></div></div><div class="hiw-ledger-photo">${photo('speaker')}</div></div>`
 ];
 const steps=[
  {tab:'Inizia',title:'Crea il gruppo o scegli il regalo',support:'',cta:'Organizza un regalo di gruppo'},
  {tab:'Condividi',title:'Proponi le opzioni o raccogli le adesioni',support:'Con un link su WhatsApp',cta:'Organizza un regalo di gruppo'},
  {tab:'Biglietto',title:'Prepara il biglietto',support:'Aggiungi il messaggio e le firme',cta:'Organizza un regalo di gruppo'},
  {tab:'Regalo',title:'Consegna il regalo',support:'Consegna il regalo o manda un’anteprima',cta:'Organizza un regalo di gruppo'},
  {tab:'Rimborsi',title:'Tieni il conto dei rimborsi',support:'Fatti rimborsare con PayPal, Satispay o bonifico',cta:'Organizza un regalo di gruppo'}
 ];
 window.renderGiftyHowItWorks=({action}={})=>`<section class="gifty-how" id="come-funziona" aria-labelledby="hiw-title"><div class="hiw-inner"><div class="hiw-heading"><h2 id="hiw-title">Come funziona</h2><div class="hiw-pager"><button type="button" data-hiw-move="-1" aria-label="Passaggio precedente" disabled>←</button><button type="button" data-hiw-move="1" aria-label="Passaggio successivo">→</button></div></div><div class="hiw-tabs" role="tablist" aria-label="Come funziona Gifty">${steps.map((step,i)=>`<button type="button" role="tab" id="hiw-tab-${i}" aria-controls="hiw-panel-${i}" aria-selected="${i===0}" tabindex="${i===0?0:-1}" data-hiw-step="${i}"><span>${i+1}</span>${step.tab}</button>`).join('')}</div><div class="hiw-story">${steps.map((step,i)=>`<div class="hiw-panel" id="hiw-panel-${i}" role="tabpanel" aria-labelledby="hiw-tab-${i}" tabindex="0" ${i===0?'':'hidden'}><div class="hiw-copy"><span class="hiw-step-number" aria-hidden="true">0${i+1}</span><h3>${step.title}</h3>${step.support?`<p>${step.support}</p>`:''}${i===0?`<div class="hiw-cta">${step.href?`<a class="link" href="#${step.href}">${step.cta}<span aria-hidden="true"> →</span></a>`:action?action(step.cta,'new-group','secondary'):`<a class="button secondary" href="#start">${step.cta}</a>`}</div>`:''}</div><div class="hiw-tabletop" aria-hidden="true">${ribbon}${scenes[i]}</div></div>`).join('')}</div></div></section>`;
 function selectStep(section,index,focus=false){const tabs=[...section.querySelectorAll('[role="tab"]')];if(index<0||index>=tabs.length)return;tabs.forEach((tab,i)=>{tab.setAttribute('aria-selected',String(i===index));tab.tabIndex=i===index?0:-1;section.querySelector('#hiw-panel-'+i).hidden=i!==index;});section.querySelector('[data-hiw-move="-1"]').disabled=index===0;section.querySelector('[data-hiw-move="1"]').disabled=index===tabs.length-1;if(focus)tabs[index].focus({preventScroll:true});}
 document.addEventListener('click',event=>{const target=event.target.closest('[data-hiw-step],[data-hiw-move]');if(!target)return;const section=target.closest('.gifty-how');if(!section)return;const current=Number(section.querySelector('[aria-selected="true"]').dataset.hiwStep);selectStep(section,target.hasAttribute('data-hiw-step')?Number(target.dataset.hiwStep):current+Number(target.dataset.hiwMove));});
 document.addEventListener('keydown',event=>{const tab=event.target.closest('.hiw-tabs [role="tab"]');if(!tab||!['ArrowRight','ArrowLeft','Home','End'].includes(event.key))return;event.preventDefault();const section=tab.closest('.gifty-how'),count=section.querySelectorAll('[role="tab"]').length,current=Number(tab.dataset.hiwStep);selectStep(section,event.key==='Home'?0:event.key==='End'?count-1:(current+(event.key==='ArrowRight'?1:-1)+count)%count,true);});
})();
